receipt_no = #{receiptNo}, receipt_type = #{receiptType}, warehouse_id = #{warehouseId}, supplier_id = #{supplierId}, order_status = #{orderStatus}, total_quantity = #{totalQuantity}, actual_quantity = #{actualQuantity}, qualified_quantity = #{qualifiedQuantity}, unqualified_quantity = #{unqualifiedQuantity}, arrival_time = #{arrivalTime}, inspection_time = #{inspectionTime}, complete_time = #{completeTime}, source_order_no = #{sourceOrderNo}, remark = #{remark}, update_by = #{updateBy}, update_time = NOW()
