SELECT

FROM wms_receipt_order ro
LEFT JOIN wms_warehouse w ON ro.warehouse_id = w.id
LEFT JOIN wms_supplier s ON ro.supplier_id = s.id

    AND ro.receipt_type = #{receiptType}
    AND ro.order_status = #{orderStatus}
    AND ro.warehouse_id = #{warehouseId}
    AND ro.supplier_id = #{supplierId}
    AND ro.create_time >= #{startTime}
    AND ro.create_time <= #{endTime}

ORDER BY ro.create_time DESC
LIMIT #{query.pageNum}, #{query.pageSize}

